<?php
require_once __DIR__ . '/_bootstrap.php';customerPostCsrf();$message='';if($_SERVER['REQUEST_METHOD']==='POST'){$product=(int)($_POST['product_id']??0);$rating=max(1,min(5,(int)($_POST['rating']??5)));$body=trim((string)($_POST['review']??''));if(!$product||$body==='')$message='Select a product and write a review.';else{customerQuery('INSERT INTO reviews (user_id,product_id,rating,review,status) VALUES (?,?,?,?,?)',[$customerId,$product,$rating,$body,'pending']);$message='Thanks. Your review is awaiting moderation.';}}$reviews=customerRows('SELECT r.rating,r.review,r.created_at,p.name FROM reviews r LEFT JOIN products p ON p.id=r.product_id WHERE r.user_id=? ORDER BY r.created_at DESC',[$customerId]);customerPageStart('My reviews','Reviews');?><div class="cw-title"><div><h1>My reviews</h1><p>Share useful feedback with the Quincy community.</p></div></div><?php if($message):?><div class="cw-alert"><?=e($message)?></div><?php endif;?><section class="cw-card" style="max-width:720px"><h2>Write a review</h2><form class="cw-form" method="post"><?=csrfField()?><label>Product ID<input type="number" name="product_id" required placeholder="From your order details"></label><label>Rating<select name="rating"><?php for($r=5;$r>=1;$r--):?><option value="<?=$r?>"><?=$r?> / 5</option><?php endfor;?></select></label><label>Your review<textarea name="review" required></textarea></label><button class="cw-btn" type="submit">Submit review</button></form></section><section class="cw-card" style="margin-top:18px"><h2>Submitted reviews</h2><?php if(!$reviews):?><div class="cw-empty">No reviews submitted yet.</div><?php else:foreach($reviews as $r):?><article style="padding:13px 0;border-bottom:1px solid #e7edf5"><strong><?=e($r['name']??'Product')?></strong> <span class="badge"><?= (int)$r['rating']?> / 5</span><p><?=e($r['review'])?></p><small class="muted"><?=e($r['created_at'])?></small></article><?php endforeach;endif;?></section><?php customerPageEnd();?>